 internal static class SmallManualProtocolTests
 {
  const string Anchor="11111111-1111-4111-8111-111111111111", Campaign="22222222-1111-4111-8111-111111111111", Area="0123456789abcdef0123456789abcdef";
  static string fixturePath; static int pass,fail;
  static int Main(string[] args) { AppDomain.CurrentDomain.AssemblyResolve += (s,e) => new AssemblyName(e.Name).Name=="Newtonsoft.Json"?Assembly.LoadFrom(args[1]):null; return Run(args[0]); }
  static void Check(string name,Action action){try{action();pass++;Console.WriteLine("PASS "+name);}catch(Exception e){fail++;Console.WriteLine("FAIL "+name+": "+e);}}
  static void Require(bool b,string reason){if(!b)throw new InvalidOperationException(reason);}
  static void Refused(Action action){bool refused=false;try{action();}catch{refused=true;}Require(refused,"Malformed admission accepted.");}
  static int Run(string file)
  {
   fixturePath=file;
   Check("actual Small body and declaration projection avoids derived PoseVector3 recursion",()=>{
    var observed=new SmallRiderBodyObservation { OriginalSizeOrdinal=3, EffectiveSizeOrdinal=3,
     MountBlueprintGuid=DeclaredSmallRiderBody.HorseBlueprintGuid, MountSizeOrdinal=5,
     RaceGuid=new string('1',32), PresetGuid=new string('2',32), Gender="Male", SkeletonName="NativeSmall",
     NativeRaceAndPresetIdentityExact=true, NativeSkeletonIsExactPreset=true, NativeRigAvailable=true,
     AvatarLocalScale=new PoseVector3(1.1f,1f,0.9f), DollEquipmentEntityIds=new[]{new string('3',32)},
     CurrentEquipmentBlueprints=new string[12], ActiveVisualEquipmentNames=new[]{"native-small"} };
    var fixtureBody=Chunk7SmallPoseObservation.Body(observed,true);
    var legacyBody=Chunk7SmallPoseObservation.Body(observed,false);
    Require(fixtureBody.Properties().Count()==20&&fixtureBody["avatarLocalScale"]["x"].Value<float>()==1.1f&&
     fixtureBody["avatarLocalScale"]["Normalized"]==null&&legacyBody["AvatarLocalScale"]["X"].Value<float>()==1.1f&&
     legacyBody["AvatarLocalScale"]["Normalized"]==null,"Small body evidence included derived vector properties or lost native scale.");
    var body=new DeclaredSmallRiderBody("small-test-horse-v1",new string('a',64),observed.RaceGuid,observed.PresetGuid,
     observed.Gender,observed.SkeletonName,false,false,observed.AvatarLocalScale,observed.DollEquipmentEntityIds,
     observed.CurrentEquipmentBlueprints,observed.ActiveVisualEquipmentNames);
    var pose=new MountedRiderPoseProfile("small-test-horse-v1","Pelvis",new PoseVector3(0f,0.1f,0f),new PoseVector3(1f,0f,0f),
     new MountedRiderLegPoseProfile("L_Thigh","L_Calf","L_Foot",new PoseVector3(-0.2f,-0.3f,0.1f),new PoseVector3(-0.2f,0f,0.1f),new PoseVector3(0f,0f,0f)),
     new MountedRiderLegPoseProfile("R_Thigh","R_Calf","R_Foot",new PoseVector3(0.2f,-0.3f,0.1f),new PoseVector3(0.2f,0f,0.1f),new PoseVector3(0f,0f,0f)));
    var declaration=new DeclaredSmallMountedProfile(body,pose,new string('b',64),new PoseVector3(0f,-0.16f,0f),new PoseVector3(0f,-0.12f,0f),new PoseVector3(0f,0f,0f));
    var projected=Chunk7SmallPoseObservation.Declaration(declaration);
    Require(projected["pose"]["PelvisPositionOffset"]["Y"].Value<float>()==0.1f&&projected["pose"]["LeftLeg"]["FootTargetFromThigh"]["X"].Value<float>()==-0.2f&&
     projected["pose"]["LeftLeg"]["FootTargetFromThigh"]["Normalized"]==null&&projected["mountRootOffset"]["Y"].Value<float>()==-0.16f,
     "Small declaration evidence included derived vectors or lost explicit offsets.");
   });
   Check("qualified Manual declaration passes pure request validation only",()=>{var r=Request();Require(r.Validate().Count==0,string.Join(" | ",r.Validate()));Require(r.ExpectedNativeLoadType=="Manual"&&ReferenceEquals(r.SelectedChunk7Fixture,r.PersistenceLoad),"Wrong native load authority.");});
   Check("unchanged Working remote Auto protocol",()=>{var r=OldRequest();Require(r.Validate().Count==0,string.Join(" | ",r.Validate()));Require(r.ExpectedNativeLoadType=="Auto"&&ReferenceEquals(r.SelectedChunk7Fixture,r.Fixture.Working),"Legacy route changed.");});
   foreach(var name in new[]{"source-alias","missing-source","old-source-alias","foreign-family","self-source","dot-source","id-alias","noncanonical-id","input-hash","Working-campaign","Working-bytes","Auto","zero-number","overflow-number","leading-zero","write-case","other-selection","unknown-case"})Check("protocol refuses "+name,()=>{var r=Request();switch(name){case "source-alias":r.SmallCalibration.Source=OldRequest().SmallCalibration.Source;break;case "missing-source":r.SmallCalibration.ManualSource=null;break;case "old-source-alias":r.SmallCalibration.Case=Chunk7SmallCalibrationSelection.CaseName;break;case "foreign-family":r.Scenario=Chunk7OrdinaryFieldSelection.Scenario;break;case "self-source":r.SmallCalibration.ManualSource.SourceRunId=r.RunId;break;case "dot-source":r.SmallCalibration.ManualSource.SourceRunId="..";break;case "id-alias":r.SmallCalibration.ManualSource.PetId=r.SmallCalibration.ManualSource.ActorId;break;case "noncanonical-id":r.SmallCalibration.ManualSource.ActorId=r.SmallCalibration.ManualSource.ActorId.ToUpperInvariant();r.SmallCalibration.ManualSource.PetId="bad";break;case "input-hash":r.PersistenceLoad.Sha256=new string('8',64);break;case "Working-campaign":r.PersistenceLoad.GameId=Anchor;break;case "Working-bytes":r.PersistenceLoad.Sha256=r.Fixture.Working.Sha256;break;case "Auto":r.PersistenceLoad.FileName="Auto_1.zks";break;case "zero-number":r.PersistenceLoad.FileName="Manual_0_KMC_C7_ACQUIRED_FIELD.zks";break;case "overflow-number":r.PersistenceLoad.FileName="Manual_2147483648_KMC_C7_ACQUIRED_FIELD.zks";break;case "leading-zero":r.PersistenceLoad.FileName="Manual_07_KMC_C7_ACQUIRED_FIELD.zks";break;case "write-case":r.PersistenceCase="multi-exploration-manual";break;case "other-selection":r.AcquiredManual=new Chunk7AcquiredManualSelection();break;case "unknown-case":r.SmallCalibration.Case="any";break;}Require(r.Validate().Count>0,"Invalid request admitted.");});
   foreach(var legacy in new[]{false,true})Check("empty compiled catalogue remains mandatory "+legacy,()=>{var r=legacy?OldRequest():Request();var before=MountedRiderProfileCatalog.Small.Count;Refused(()=>r.SmallCalibration.RequireCompiledDeclaration());Require(before==MountedRiderProfileCatalog.Small.Count&&before==0,"A request inserted a declaration.");});
   Check("actual request projection preserves legacy five properties",()=>{var s=Chunk7EvidenceDto.Request(OldRequest().SmallCalibration);Require(s.Properties().Select(x=>x.Name).OrderBy(x=>x).SequenceEqual(new[]{"case","source","profileId","nativeInventorySha256","nativeCalibrationSha256"}.OrderBy(x=>x)),s.ToString());Require(s["source"] is JObject&&s["manualSource"]==null,"Legacy source shape changed.");});
   Check("actual new DTO projection excludes legacy source",()=>{var s=Chunk7EvidenceDto.Request(Request().SmallCalibration);Require(s["source"]==null&&s["manualSource"] is JObject,"Ambiguous source shape.");var back=s.ToObject<Chunk7SmallCalibrationSelection>();Require(back.UsesManualField&&back.Validate(Chunk7SmallCalibrationSelection.Scenario,"current").Count==0,"Actual DTO round trip changed.");});
   Check("one immutable native Manual authority",()=>{var r=Request();var a=Scope(r);Require(a.MatchesReadOnlySmallManualPlan(r.PersistenceLoad),"Exact immutable plan refused.");Require(!a.MatchesReadOnlyFieldPlan(r.PersistenceLoad),"New case borrowed Auto authority.");var t=Target(r);Require(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,t,a.Root)==null,"Exact native load refused.");Require(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,t,a.Root)!=null,"Second native load admitted.");Require(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,t,a.Root)!=null,"Readonly source write admitted.");Require(a.AdmittedNativeLoadRequests==1&&a.AdmittedNativeWriteRequests==0,"Refusal changed quotas.");});
   foreach(var name in new[]{"writable","write-cap","load-cap","extra-leaf","wrong-area","wrong-hash","wrong-type","wrong-campaign","wrong-name"})Check("authority refuses "+name,()=>{var r=Request();var e=Entry(r);var list=new List<PersistenceSaveEntry>{e};int? writes=null;var loads=1;switch(name){case "writable":e.Writable=true;break;case "write-cap":writes=1;break;case "load-cap":loads=2;break;case "extra-leaf":list.Add(new PersistenceSaveEntry{FileName="Manual_8_other.zks",InternalName="other",SaveType="Manual",Area=Area,Writable=true});break;case "wrong-area":r.PersistenceLoad.Area=new string('e',32);break;case "wrong-hash":r.PersistenceLoad.Sha256=new string('e',64);break;case "wrong-type":e.SaveType="Auto";break;case "wrong-campaign":r.PersistenceLoad.GameId=Anchor;break;case "wrong-name":r.PersistenceLoad.InternalName="Other";break;}SmallManualVirtual.SourceLeaf=Chunk7AcquiredManualSelection.NativeOutputLeaf(7);var a=new PersistenceSaveAuthorization(SmallManualVirtual.Root,Campaign,"Native",new string('a',64),list,null,null,writes,loads);Require(!a.MatchesReadOnlySmallManualPlan(r.PersistenceLoad),"Foreign plan accepted.");});
   Check("actual source artifact predicate admits selected paid field ancestry",()=>{var r=Request();Require(Chunk7SmallCalibrationScenario.RequireManualArtifact(r,Artifact(r))!=null,"Valid source refused.");});
   foreach(var name in new[]{"failed","foreign-run","foreign-binary","wrong-output","wrong-campaign","cumulative","two-owner-property","ordinary-existing","wrong-actor","wrong-pet","not-base-only","output-autosave","incomplete-cleanup","changed-progression","save-after-field","scalar-array"})Check("actual source predicate refuses "+name,()=>{var r=Request();var a=Artifact(r);var o=(JObject)a["observations"];switch(name){case "failed":a["status"]="FAIL";break;case "foreign-run":a["runId"]="other";break;case "foreign-binary":a["dllSha256"]=new string('8',64);break;case "wrong-output":o["nativeWrite"]["fileName"]="Auto_1.zks";break;case "wrong-campaign":o["nativeWrite"]["gameId"]=Anchor;break;case "cumulative":o["selection"]["case"]=Chunk7AcquiredManualSelection.TwoOwnerCaseName;break;case "two-owner-property":o["twoOwners"]=new JArray();break;case "ordinary-existing":o["sourceAcquisition"]["selection"]["case"]="existing-ranger-horse";break;case "wrong-actor":o["sourceAcquisition"]["field"]["actorId"]="44444444-1111-4111-8111-111111111111";break;case "wrong-pet":o["selection"]["petId"]="44444444-1111-4111-8111-111111111111";break;case "not-base-only":o["selection"]["baseGameOnly"]=false;break;case "output-autosave":o["nativeWrite"]["autoLevelup"]=true;break;case "incomplete-cleanup":o["cleanup"]["custodySettled"]=false;break;case "changed-progression":o["afterSaveArrangement"]["money"]=1;break;case "save-after-field":o["sourceAcquisition"]["nativeWrite"]["saveBeforeFieldSelection"]=false;break;case "scalar-array":o["selection"]["case"]=new JArray(o["selection"]["case"]);break;}Refused(()=>Chunk7SmallCalibrationScenario.RequireManualArtifact(r,a));});
   Check("F09 owner-seed Manual remains a distinct cross-candidate request",()=>{var r=F09Request();Require(r.Validate().Count==0,string.Join(" | ",r.Validate()));Require(r.SmallCalibration.UsesFixtureManualField&&!r.SmallCalibration.UsesManualField&&r.ExpectedNativeLoadType=="Manual"&&ReferenceEquals(r.SelectedChunk7Fixture,r.PersistenceLoad),"F09 request borrowed acquired or Auto authority.");var dto=Chunk7EvidenceDto.Request(r.SmallCalibration);Require(dto["fixtureSource"] is JObject&&dto["manualSource"]==null&&dto["source"]==null,"F09 provenance was relabeled.");});
   foreach(var name in new[]{"acquired-alias","remote-alias","same-run","wrong-receipt","wrong-leaf","wrong-name","wrong-hash","working-campaign"})Check("F09 request refuses "+name,()=>{var r=F09Request();switch(name){case "acquired-alias":r.SmallCalibration.ManualSource=Request().SmallCalibration.ManualSource;break;case "remote-alias":r.SmallCalibration.Source=OldRequest().SmallCalibration.Source;break;case "same-run":r.SmallCalibration.FixtureSource.SourceRunId=r.RunId;break;case "wrong-receipt":r.SmallCalibration.FixtureSource.ColdReceiptSha256="bad";break;case "wrong-leaf":r.PersistenceLoad.FileName="Manual_7_KMC_C7_ACQUIRED_FIELD.zks";break;case "wrong-name":r.PersistenceLoad.InternalName=Chunk7AcquiredManualSelection.OutputName;break;case "wrong-hash":r.PersistenceLoad.Sha256=new string('9',64);break;case "working-campaign":r.PersistenceLoad.GameId=Anchor;break;}Require(r.Validate().Count>0,"Foreign F09 request admitted.");});
   Check("F09 native authority permits one load and zero writes",()=>{var r=F09Request();var a=Scope(r);Require(a.MatchesReadOnlySmallFixturePlan(r.PersistenceLoad),"Exact F09 plan refused.");Require(!a.MatchesReadOnlySmallManualPlan(r.PersistenceLoad)&&!a.MatchesReadOnlyFieldPlan(r.PersistenceLoad),"F09 source borrowed another plan.");var t=Target(r);Require(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,t,a.Root)==null,"F09 native load refused.");Require(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,t,a.Root)!=null&&a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,t,a.Root)!=null,"F09 granted repeated load or write.");});
   Check("F09 actual artifact predicate admits exact source",()=>{var r=F09Request();Require(Chunk7SmallCalibrationScenario.RequireFixtureManualArtifact(r,F09Artifact(r))!=null,"Exact F09 source refused.");});
   foreach(var name in new[]{"failed","same-binary","wrong-archive","wrong-main","missing-small","not-two-pairs","changed-body","changed-arrangement","cleanup","write-auto"})Check("F09 artifact refuses "+name,()=>{var r=F09Request();var a=F09Artifact(r);var o=a["observations"];switch(name){case "failed":a["status"]="FAIL";break;case "same-binary":r.DllSha256=(string)a["dllSha256"];break;case "wrong-archive":o["nativeWrite"]["sha256"]=new string('8',64);break;case "wrong-main":o["savedWorld"]["mainActorId"]=r.SmallCalibration.FixtureSource.ActorId;break;case "missing-small":((JArray)o["savedWorld"]["party"]).RemoveAt(5);break;case "not-two-pairs":((JArray)o["acquiredOwners"]).RemoveAt(0);break;case "changed-body":o["savedBodyObservation"]["raceGuid"]="changed";break;case "changed-arrangement":o["afterSaveArrangement"]["money"]=1;break;case "cleanup":o["cleanup"]["custodySettled"]=false;break;case "write-auto":o["nativeWrite"]["autoLevelup"]=true;break;}Refused(()=>Chunk7SmallCalibrationScenario.RequireFixtureManualArtifact(r,a));});
   Console.WriteLine("TOTAL PASS="+pass+" FAIL="+fail);return fail==0?0:1;
  }
  static RuntimeSaveDescriptor Descriptor(string name,string leaf,string hash,string game=Anchor)=>new RuntimeSaveDescriptor{InternalName=name,FileName=leaf,Sha256=hash,Length=200,LastWriteTimeUtcTicks=638960000000000000L,GameId=game,GameName=game==Anchor?"Anchor":"Native",Area=Area};
  static RuntimeRequest Request()=>new RuntimeRequest{SchemaVersion=2,RunId="small-manual-test",Scenario=Chunk7SmallCalibrationSelection.Scenario,SmallCalibration=new Chunk7SmallCalibrationSelection{Case=Chunk7SmallCalibrationSelection.ManualCaseName,ProfileId="small-synthetic-horse-v1",NativeInventorySha256=new string('1',64),NativeCalibrationSha256=new string('2',64),ManualSource=new Chunk7SmallManualSourceSelection{SourceRunId="acquired-source",SourceArtifactSha256=new string('e',64),SourceArchiveSha256=new string('f',64),ActorId="11111111-2222-4333-8444-555555555555",PetId="66666666-7777-4888-8999-aaaaaaaaaaaa"}},PersistenceLoad=Descriptor(Chunk7AcquiredManualSelection.OutputName,Chunk7AcquiredManualSelection.NativeOutputLeaf(7),new string('f',64),Campaign),Branch="codex/mounted-combat-chunk7-foundation",Commit=new string('1',40),ProductVersion=BuildIdentity.ProductVersion,DllSha256=new string('2',64),DllMvid=Anchor,TransactionToken=new string('3',64),EvidenceRoot=SmallManualVirtual.Root+@"\evidence",Fixture=new RuntimeFixtureIdentity{Baseline=Descriptor("KMC_AUTOMATION_BASELINE","Manual_298_KMC_AUTOMATION_BASELINE.zks",new string('a',64)),Working=Descriptor("KMC_AUTOMATION_WORKING","Manual_299_KMC_AUTOMATION_WORKING.zks",new string('b',64)),WriteAuthorization=new RuntimeSaveWriteAuthorization{Mode="working-only",AllowedInternalName="KMC_AUTOMATION_WORKING",AllowedFileName="Manual_299_KMC_AUTOMATION_WORKING.zks",BaselineImmutable=true}},QualificationSuite=new RuntimeQualificationSuiteIdentity{SuiteId="synthetic-suite",SnapshotSha256=new string('4',64)}};
  static RuntimeRequest OldRequest(){var r=Request();r.SmallCalibration.Case=Chunk7SmallCalibrationSelection.CaseName;r.SmallCalibration.Source=new Chunk7OrdinaryFieldSelection{Case=Chunk7OrdinaryFieldSelection.CaseName,SourceRunId="old-source",SourceArtifactSha256=new string('e',64),SourceArchiveSha256=new string('f',64),ActorId=r.SmallCalibration.ManualSource.ActorId,PetId=r.SmallCalibration.ManualSource.PetId};r.SmallCalibration.ManualSource=null;r.PersistenceLoad=Descriptor("Autosave","Auto_1.zks",new string('f',64));return r;}
  static RuntimeRequest F09Request(){var r=Request();var old=r.SmallCalibration.ManualSource;r.SmallCalibration.Case=Chunk7SmallCalibrationSelection.FixtureManualCaseName;r.SmallCalibration.ManualSource=null;r.SmallCalibration.FixtureSource=new Chunk7SmallFixtureManualSourceSelection{SourceRunId="f09-source",SourceArtifactSha256=new string('e',64),SourceArchiveSha256=new string('f',64),ColdReceiptSha256=new string('c',64),ActorId=old.ActorId,PetId=old.PetId};r.PersistenceLoad=Descriptor(Chunk7SmallFixtureManualSourceSelection.NativeName,"Manual_304_KMC_C7_SMALL_FIXTURE.zks",new string('f',64),Campaign);return r;}
  static JObject F09Artifact(RuntimeRequest r){var s=r.SmallCalibration.FixtureSource;var main="12345678-1234-4234-8234-123456789abc";var priorHorse="23456789-1234-4234-8234-123456789abc";var other=new[]{"34567890-1234-4234-8234-123456789abc","45678901-1234-4234-8234-123456789abc","56789012-1234-4234-8234-123456789abc"};var party=new JArray(new[]{main,priorHorse,s.ActorId,s.PetId}.Concat(other).Select(id=>new JObject{["id"]=id}));var arrangement=new JObject{["money"]=100,["characters"]=new JArray(new[]{main,s.ActorId}.Concat(other)),["remote"]=new JArray()};var body=new JObject{["raceGuid"]="race"};var o=new JObject{["contract"]="owner-seed-unmounted-small-fixture-v1",["fixtureSetupOnly"]=true,["beforeSaveArrangement"]=arrangement.DeepClone(),["afterSaveArrangement"]=arrangement,["bodyObservation"]=body.DeepClone(),["savedBodyObservation"]=body,["savedWorld"]=new JObject{["mainActorId"]=main,["party"]=party},["acquiredOwners"]=new JArray(new JObject{["riderId"]=main,["horseId"]=priorHorse,["reciprocal"]=true},new JObject{["riderId"]=s.ActorId,["horseId"]=s.PetId,["reciprocal"]=true}),["nativeWrite"]=new JObject{["sha256"]=s.SourceArchiveSha256,["fileName"]=r.PersistenceLoad.FileName,["internalName"]=r.PersistenceLoad.InternalName,["type"]="Manual",["gameId"]=r.PersistenceLoad.GameId,["gameName"]=r.PersistenceLoad.GameName,["area"]=r.PersistenceLoad.Area,["autoLevelup"]=false},["cleanup"]=new JObject{["custodySettled"]=true,["sourceUnchanged"]=true}};return new JObject{["runId"]=s.SourceRunId,["scenario"]=Chunk7SmallFixtureSelection.Scenario,["evidenceKind"]="chunk7-small-fixture-evidence",["status"]="PASS",["errors"]=new JArray(),["commit"]="784a6296f9e0d91c44ad25dda826db57f609e929",["dllSha256"]="8f7f89769c82e0ac15f5d972441d29e68d6f67ff4ad942fe55f25ece12047d89",["dllMvid"]="bf98be50-898a-41b3-88f0-78959a0ea1a3",["observations"]=o};}
  static JObject Artifact(RuntimeRequest r){var f=JObject.Parse(File.ReadAllText(fixturePath));var o=(JObject)f["artifact"]["observations"]["source"]["acquiredManual"].DeepClone();o["nativeWrite"]["area"]=Area;return new JObject{["runId"]=r.SmallCalibration.ManualSource.SourceRunId,["scenario"]=Chunk7AcquiredManualSelection.Scenario,["evidenceKind"]="chunk7-acquired-manual-evidence",["status"]="PASS",["errors"]=new JArray(),["commit"]=r.Commit,["dllSha256"]=r.DllSha256,["dllMvid"]=r.DllMvid,["observations"]=o};}
  static PersistenceSaveEntry Entry(RuntimeRequest r)=>new PersistenceSaveEntry{FileName=r.PersistenceLoad.FileName,InternalName=r.PersistenceLoad.InternalName,SaveType="Manual",Area=r.PersistenceLoad.Area,InitialSha256=r.PersistenceLoad.Sha256};
  static PersistenceSaveAuthorization Scope(RuntimeRequest r){SmallManualVirtual.SourceLeaf=r.PersistenceLoad.FileName;return new PersistenceSaveAuthorization(SmallManualVirtual.Root,Campaign,"Native",new string('a',64),new[]{Entry(r)},null,null,null,1);}
  static RuntimeSaveTarget Target(RuntimeRequest r)=>new RuntimeSaveTarget{InternalName=r.PersistenceLoad.InternalName,FileName=r.PersistenceLoad.FileName,FullPath=SmallManualVirtual.Root+@"\Saved Games\"+r.PersistenceLoad.FileName,SaveType="Manual",GameId=Campaign,GameName="Native",Area=Area};
 }
 internal static class SmallManualVirtual
 {
  internal const string Root=@"C:\SmallManualVirtual\run";internal static string SourceLeaf="Manual_7_KMC_C7_ACQUIRED_FIELD.zks";
  internal static IEnumerable<string> EnumerateFileSystemEntries(string path)=>new[]{path+"\\"+SourceLeaf};
  internal static bool Exists(string path)=>!path.EndsWith(".zks",StringComparison.Ordinal);
  internal static void RequireDirectory(string path){if(string.IsNullOrEmpty(path))throw new InvalidOperationException();}
